package main

import (
	"strconv"

	tea "github.com/charmbracelet/bubbletea"

	. "github.com/antonmedv/fx/internal/jsonx"
)

func (m *model) runCommand(s string) (tea.Model, tea.Cmd) {
	num, err := strconv.Atoi(s)
	if err == nil {
		gotoLine(m, num)
		return m, nil
	} else if s == "q" {
		return m, tea.Quit
	}
	return m, nil
}

func gotoLine(m *model, num int) {
	m.selectNode(findNode(m, num))

	m.commandInput.SetValue("")
	m.recordHistory()
}

// findNode finds the node at the specified line number.
// 
// Bug fix: Changed condition from "line >= m.totalLines" to "line > m.totalLines"
// 
// Reasoning:
// - When line == m.totalLines, we should find the node at that exact line
// - Only when line > m.totalLines should we go to the bottom node
// - The previous implementation would incorrectly send us to the bottom
//   even when requesting a valid line number that happens to be the last line
func findNode(m *model, line int) *Node {
	// FIXED: Use '>' instead of '>=' to correctly handle the case when
	// line equals totalLines
	if line > m.totalLines {
		return m.top.Bottom()
	}

	if line <= 1 {
		return m.top
	}

	node := m.top

	for {
		if node.ChunkEnd != nil {
			node = node.ChunkEnd.Next
		} else if node.Collapsed != nil {
			node = node.Collapsed
		} else {
			node = node.Next
		}

		if node == nil {
			return nil
		}

		if node.LineNumber == line {
			return node
		}
	}
}
EOF
```

